  "basis" handover_basis NOT NULL,
  "authorization_reference" text NOT NULL,
  "reason" text NOT NULL,
  "performed_at" timestamptz NOT NULL DEFAULT (CURRENT_TIMESTAMP),
  CONSTRAINT "ck_handover_one_resource" CHECK (num_nonnulls(output_id, group_id) = 1),
  CONSTRAINT "ck_handover_different_holder" CHECK (previous_user_id <> new_user_id),
  CONSTRAINT "ck_handover_no_self_acquisition" CHECK (performed_by <> new_user_id),
  CONSTRAINT "ck_handover_evidence" CHECK (length(btrim(reason)) > 0 AND length(btrim(authorization_reference)) > 0)
);

CREATE TABLE "output_revisions" (
  "id" uuid PRIMARY KEY DEFAULT (gen_random_uuid()),
